div.script:

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

let gameState = 'START'; // START, PLAYING, GAMEOVER
let score = 0;
let lives = 3;
let highscore = parseInt(localStorage.getItem('feather_catcher_highscore') || '0', 10);

const player = {
  x: 240,
  y: 630,
  width: 60,
  height: 35,
  speed: 8,
  dx: 0
};

let items = [];
let frameCount = 0;
let itemSpawnRate = 45;

function resetGame() {
  player.x = 240;
  items = [];
  score = 0;
  lives = 3;
  frameCount = 0;
  gameState = 'PLAYING';
}

function startGame() {
  if (gameState === 'START' || gameState === 'GAMEOVER') {
    resetGame();
  }
}

// Controls
const keys = {};
window.addEventListener('keydown', function(e) {
  if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys['left'] = true;
  if (e.code === 'ArrowRight' || e.code === 'KeyD') keys['right'] = true;
  if (e.code === 'Space' && (gameState === 'START' || gameState === 'GAMEOVER')) {
    e.preventDefault();
    startGame();
  }
});

window.addEventListener('keyup', function(e) {
  if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys['left'] = false;
  if (e.code === 'ArrowRight' || e.code === 'KeyD') keys['right'] = false;
});

// Touch & Mouse Support
canvas.addEventListener('click', function() {
  startGame();
});

canvas.addEventListener('mousemove', function(e) {
  if (gameState === 'PLAYING') {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    player.x = (e.clientX - rect.left) * scaleX - player.width / 2;
  }
});

canvas.addEventListener('touchmove', function(e) {
  if (gameState === 'PLAYING' && e.touches.length > 0) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    player.x = (e.touches[0].clientX - rect.left) * scaleX - player.width / 2;
  }
}, { passive: true });

function spawnItem() {
  const isRock = Math.random() < 0.28; // 28% chance for a rock
  const size = isRock ? 32 : 24;
  items.push({
    x: Math.random() * (canvas.width - size),
    y: -40,
    size: size,
    speed: Math.random() * 2 + 2.5 + (score * 0.05), // gets faster as score increases
    type: isRock ? 'ROCK' : 'FEATHER'
  });
}

function update() {
  if (gameState !== 'PLAYING') return;

  // Move Player via Keyboard
  if (keys['left']) player.x -= player.speed;
  if (keys['right']) player.x += player.speed;

  // Boundaries
  if (player.x < 0) player.x = 0;
  if (player.x > canvas.width - player.width) player.x = canvas.width - player.width;

  // Spawn Items
  frameCount++;
  if (frameCount % Math.max(20, itemSpawnRate - Math.floor(score / 5)) === 0) {
    spawnItem();
  }

  // Update Items
  for (let i = items.length - 1; i >= 0; i--) {
    items[i].y += items[i].speed;

    // Collision with Player
    if (
      items[i].x < player.x + player.width &&
      items[i].x + items[i].size > player.x &&
      items[i].y < player.y + player.height &&
      items[i].y + items[i].size > player.y
    ) {
      if (items[i].type === 'FEATHER') {
        score++;
        if (score > highscore) {
          highscore = score;
          localStorage.setItem('feather_catcher_highscore', highscore);
        }
      } else {
        // Hit Rock
        lives--;
        if (lives <= 0) {
          gameState = 'GAMEOVER';
        }
      }
      items.splice(i, 1);
      continue;
    }

    // Remove off-screen items
    if (items[i].y > canvas.height) {
      if (items[i].type === 'FEATHER') {
        // Missed feather penalty if desired, or let it slide
      }
      items.splice(i, 1);
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Background gradient details
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw Items
  for (let i = 0; i < items.length; i++) {
    if (items[i].type === 'FEATHER') {
      ctx.fillStyle = '#facc15';
      ctx.beginPath();
      ctx.arc(items[i].x + items[i].size/2, items[i].y + items[i].size/2, items[i].size/2, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#0f172a';
      ctx.font = '14px system-ui';
      ctx.textAlign = 'center';
      ctx.fillText('🪶', items[i].x + items[i].size/2, items[i].y + items[i].size/2 + 5);
    } else {
      ctx.fillStyle = '#64748b';
      ctx.beginPath();
      ctx.arc(items[i].x + items[i].size/2, items[i].y + items[i].size/2, items[i].size/2, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#f8fafc';
      ctx.font = '16px system-ui';
      ctx.textAlign = 'center';
      ctx.fillText('🪨', items[i].x + items[i].size/2, items[i].y + items[i].size/2 + 6);
    }
  }

  // Draw Player (Eagle Basket/Nest / Catching Area)
  ctx.fillStyle = '#38bdf8';
  ctx.fillRect(player.x, player.y, player.width, player.height);
  ctx.fillStyle = '#f8fafc';
  ctx.font = 'bold 14px system-ui';
  ctx.textAlign = 'center';
  ctx.fillText('🦅 EAGLE', player.x + player.width/2, player.y + 22);

  // UI / HUD
  if (gameState === 'START') {
    ctx.fillStyle = 'rgba(15, 23, 42, 0.88)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#38bdf8';
    ctx.font = '900 32px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText('FEATHER CATCHER', canvas.width / 2, canvas.height / 2 - 50);
    ctx.fillStyle = '#f8fafc';
    ctx.font = '600 15px system-ui';
    ctx.fillText('Catch Golden Feathers 🪶, Dodge Rocks 🪨!', canvas.width / 2, canvas.height / 2 - 5);
    ctx.fillStyle = '#94a3b8';
    ctx.font = '500 14px system-ui';
    ctx.fillText('Use Arrow Keys, Mouse, or Touch to Move', canvas.width / 2, canvas.height / 2 + 30);
    ctx.fillStyle = '#facc15';
    ctx.font = 'bold 16px system-ui';
    ctx.fillText('High Score: ' + highscore, canvas.width / 2, canvas.height / 2 + 80);
    ctx.fillStyle = '#38bdf8';
    ctx.fillText('Click or Press Space to Play', canvas.width / 2, canvas.height / 2 + 120);
  } else if (gameState === 'PLAYING') {
    ctx.fillStyle = '#f8fafc';
    ctx.font = '900 28px system-ui';
    ctx.textAlign = 'left';
    ctx.fillText('Score: ' + score, 20, 45);

    ctx.textAlign = 'right';
    ctx.fillStyle = '#ef4444';
    let hearts = '';
    for (let h = 0; h < lives; h++) hearts += '❤️ ';
    ctx.fillText(hearts, canvas.width - 20, 45);
  } else if (gameState === 'GAMEOVER') {
    ctx.fillStyle = 'rgba(15, 23, 42, 0.92)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ef4444';
    ctx.font = '900 38px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2 - 50);
    ctx.fillStyle = '#f8fafc';
    ctx.font = '700 20px system-ui';
    ctx.fillText('Final Score: ' + score, canvas.width / 2, canvas.height / 2);
    ctx.fillStyle = '#facc15';
    ctx.fillText('High Score: ' + highscore, canvas.width / 2, canvas.height / 2 + 40);
    ctx.fillStyle = '#38bdf8';
    ctx.font = '600 16px system-ui';
    ctx.fillText('Click or Press Space to Restart', canvas.width / 2, canvas.height / 2 + 100);
  }
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();
